case ANM_OP_F_ADD:
{
    float value = GET_FLOAT_VAR(1);
    float *destination = GET_FLOAT_VAR_PTR(0);
    *destination = *destination + value;
    break;
}

case ANM_OP_F_SUB:
{
    float value = GET_FLOAT_VAR(1);
    float *destination = GET_FLOAT_VAR_PTR(0);
    *destination = *destination - value;
    break;
}

