case ANM_OP_F_SET_MOD:
{
    float divisor = GET_FLOAT_VAR(2);
    float dividend = GET_FLOAT_VAR(1);
    float *destination = GET_FLOAT_VAR_PTR(0);
    *destination = static_cast<float>(fmod(
        static_cast<double>(dividend), static_cast<double>(divisor)));
    break;
}

